/**
 * Salesforce Node - Version 1.1
 * Discriminator: resource=document, operation=upload
 */


interface Credentials {
  salesforceOAuth2Api: CredentialReference;
  salesforceJwtApi: CredentialReference;
}

/** Represents a document */
export type SalesforceV11DocumentUploadParams = {
  resource: 'document';
  operation: 'upload';
/**
 * OAuth Authorization Flow
 * @default oAuth2
 */
    authentication?: 'oAuth2' | 'jwt' | Expression<string>;
/**
 * Name of the file
 */
    title: string | Expression<string>;
/**
 * Input Binary Field
 * @hint The name of the input binary field containing the file to be uploaded
 * @default data
 */
    binaryPropertyName?: string | Expression<string>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** File extension to use. If none is set, the value from the binary data will be used.
     */
    fileExtension?: string | Expression<string>;
    /** ID of the object you want to link this document to
     */
    linkToObjectId?: string | Expression<string>;
    /** The user who owns this document
     * @searchListMethod searchUsers
     * @default {"mode":"list","value":""}
     */
    ownerId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
  };
};

export type SalesforceV11DocumentUploadOutput = {
  id?: string;
  success?: boolean;
};

export type SalesforceV11DocumentUploadNode = {
  type: 'n8n-nodes-base.salesforce';
  version: 1.1;
  config: NodeConfig<SalesforceV11DocumentUploadParams> & { credentials?: Credentials };
  output?: Items<SalesforceV11DocumentUploadOutput>;
};